          )
          .pages
          .first
          .findShapeById(id)!;
      expect(leftover.angleRad, closeTo(math.pi / 2, 0.05));
      expect(
        glyphShape(leftover, 'A')!.richText.textBlock.angleRad,
        closeTo(-math.pi / 2, 0.05),
        reason: 'a second save must keep TxtAngle against Angle',
      );
    },
  );

