        '<save/>'
        '<strokecolor color="#00aa00"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        strokeRgb(extraSave),
