        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<linejoin/>'
        '<path><move x="0" y="10"/><line x="0" y="0"/><line x="40" y="0"/></path>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
