        includeHost.children.any(
          (child) =>
              child.line.hasLine && child.line.join == VsdxLineJoin.miter,
        ),
        isTrue,
        reason: 'include-shape nested omitted join leftover-bakes miter '
            'so Draw does not fillet the tile',
