        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" valign="bottom"/>'
        '<text str="CD" x="0" y="30" w="40" h="20"/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        vertOf(laterHost, 'AB'),
        VsdxVertAlign.bottom,
