        '<foreground>'
        '<rect x="40" y="40" w="20" h="10"/>'
        '<stroke/>'
        '<rect w="20" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
        id: 546,
      );
      expect(
        firstMoveXs(omitted),
        [closeTo(0, 1e-6), closeTo(shiftedX, 1e-6)],
        reason: 'omitted rect x is Number(null)=0; leftover must not keep '
            'MoveTo so Draw collectGeometry does not RelMoveTo the first '
