        '<foreground>'
        '<fillcolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor color="yellow"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
