  test(
    'mxStencil html CSS margin 16px 8px 0 omitted leftover Para for LibreOffice',
    () {
      List<List<double>> boxes(VsdxShape shape) {
        final values = <List<double>>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            final p = run.paraStyle;
            values.add([
              p.indentLeftInches,
              p.indentRightInches,
              p.spaceBeforeInches,
              p.spaceAfterInches,
            ]);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      final pad = 8 * canvasScale;
      final padX = 16 * canvasScale;
      final padB = 4 * canvasScale;
      final padL = 2 * canvasScale;
      final ua = 11 * canvasScale;
      List<Matcher> keepBox() => [
            closeTo(pad, 1e-9),
            closeTo(pad, 1e-9),
            closeTo(padX, 1e-9),
            closeTo(0, 1e-9),
          ];
      List<Matcher> omitBox() => [
            closeTo(0, 1e-9),
            closeTo(0, 1e-9),
            closeTo(ua, 1e-9),
            closeTo(ua, 1e-9),
          ];
      const keepT =
          '<text str="&lt;p style=&quot;margin:16px 8px 0&quot;&gt;AB&lt;/p&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;p&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;p style=&quot;margin:16px 8px 0&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;p&gt;AB&lt;/p&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;p style=&quot;margin:16px 8px 0&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 995,
      );
      expect(
        boxes(omitted),
        [keepBox(), omitBox()],
        reason: 'omitted html CSS margin:16px 8px 0 is UA; leftover must not keep IndLeft/SpBefore '
            'so Draw collectParaIX does not inset the later glyph '
            '(`tokens.txt` Ind*/Sp* → fo:margin-left 0.305cm vs 0cm / fo:margin-top 0.61cm vs 0.419cm / fo:margin-bottom 0cm vs 0.419cm)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$omittedFirst'
        '$keepSecond'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        boxes(keep),
        [keepBox(), keepBox()],
        reason: 'without omitted html CSS margin:16px 8px 0 leftover keeps Ind*/Sp*',
      );
      expect(
        boxes(later),
        [omitBox(), keepBox()],
        reason: 'later html CSS margin:16px 8px 0 leftover-bakes a sibling Ind*/Sp*',
      );
      expect(
        boxes(includeHost),
        [keepBox(), omitBox()],
        reason: 'include-shape nested omitted html CSS margin:16px 8px 0 leftover-bakes UA so '
            'Draw does not inherit host fo:margin-*',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        boxes(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [keepBox(), omitBox()],
        reason: 'a second save keeps leftover IndLeft/SpBefore Draw paints',
      );
      expect(
        boxes(leftoverDoc.pages.first.findShapeById(laterId)!),
        [omitBox(), keepBox()],
        reason: 'a second save keeps the later leftover IndLeft/SpBefore sibling',
      );
    },
  );

