        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 1132,
      );
      expect(
        fillCount(omitted),
        1,
        reason: 'later omitted fillcolor/strokecolor leftover-bakes none; '
            'leftover must not keep FillForegnd so Draw does not fill the '
            'later rail (`tokens.txt` FillForegnd → draw:fill-color #ff69b4)',
      );
      expect(lineCount(omitted), 1);
      expect(
        filledFg(omitted),
        hotpink,
        reason: 'NestedStencil htmlCssColorToHex paints named hotpink; '
            'fillstrokecolor leftover FillForegnd/LineColor must be #ff69b4',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="hotpink"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillstrokecolor color="hotpink"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillstrokecolor color="hotpink"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="hotpink"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        fillCount(keep),
        2,
        reason: 'without omitted fillcolor leftover keeps hotpink FillForegnd',
      );
      expect(lineCount(keep), 2);
      expect(fillCount(later), 1);
      expect(filledFg(later), hotpink);
      expect(
        fillCount(includeHost),
        1,
        reason: 'include-shape nested omitted fillcolor leftover-bakes none so '
            'Draw does not inherit host draw:fill-color',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        fillCount(leftoverDoc.pages.first.findShapeById(omittedId)!),
        1,
        reason: 'a second save keeps leftover hotpink FillForegnd Draw paints',
      );
      expect(
        filledFg(leftoverDoc.pages.first.findShapeById(omittedId)!),
        hotpink,
      );
      expect(
        fillCount(leftoverDoc.pages.first.findShapeById(laterId)!),
        1,
        reason: 'a second save keeps the later leftover FillForegnd sibling',
      );
    },
  );

