      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        colors(keep),
        everyElement(hexb4d),
        reason: 'without omitted html CSS color:#b4d leftover keeps Char.Color',
      );
      expect(
        colors(later),
        [black, hexb4d],
        reason: 'later html CSS color:#b4d leftover-bakes a sibling Char.Color',
      );
      expect(
        colors(includeHost),
        [hexb4d, black],
        reason: 'include-shape nested omitted html CSS color:#b4d leftover-bakes black '
            'so Draw does not inherit host fo:color',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        colors(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [hexb4d, black],
        reason: 'a second save keeps leftover Char.Color Draw paints',
      );
      expect(
        colors(leftoverDoc.pages.first.findShapeById(laterId)!),
        [black, hexb4d],
        reason: 'a second save keeps the later leftover Char.Color sibling',
      );
    },
  );

