          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      VsdxColor? strokedLc(VsdxShape shape) {
        VsdxColor? found;
        void walk(VsdxShape next) {
          if (next.line.hasLine) found = next.line.color;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return found;
      }

