  test(
    'mxStencil fillcolor darkcyan omitted leftover FillForegnd for LibreOffice',
    () {
      int fillCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.fill.hasFill) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      VsdxColor? filledFg(VsdxShape shape) {
        VsdxColor? found;
        void walk(VsdxShape next) {
          if (next.fill.hasFill) found = next.fill.foreground;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return found;
      }

      final darkcyan = VsdxColor.tryParse('#008b8b')!;
      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="darkcyan"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 1509,
      );
      expect(
        fillCount(omitted),
        1,
        reason: 'omitted fillcolor is setFillColor(null)/none; leftover must '
            'not keep FillForegnd so Draw collectFillAndShadow does not fill '
            'the later rail (`tokens.txt` FillForegnd → draw:fill-color '
            '#008b8b)',
      );
      expect(
        filledFg(omitted),
        darkcyan,
        reason: 'NestedStencil htmlCssColorToHex paints named darkcyan; leftover '
            'FillForegnd must be #008b8b so Draw paints the keep rail',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="darkcyan"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor color="darkcyan"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor color="darkcyan"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="darkcyan"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        fillCount(keep),
        2,
        reason: 'without omitted fillcolor leftover keeps darkcyan FillForegnd',
      );
      expect(filledFg(later), darkcyan);
      expect(fillCount(later), 1);
      expect(
        fillCount(includeHost),
        1,
        reason: 'include-shape nested omitted fillcolor leftover-bakes none so '
            'Draw does not inherit host draw:fill-color',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        fillCount(leftoverDoc.pages.first.findShapeById(omittedId)!),
        1,
        reason: 'a second save keeps leftover darkcyan FillForegnd Draw paints',
      );
      expect(
        filledFg(leftoverDoc.pages.first.findShapeById(omittedId)!),
        darkcyan,
      );
      expect(
        fillCount(leftoverDoc.pages.first.findShapeById(laterId)!),
        1,
        reason: 'a second save keeps the later leftover FillForegnd sibling',
      );
    },
  );

