  test(
    'SysML Abstract Definition leftover has no trailing Character newline for LibreOffice',
    () {
      VsdxShape? nameShape(VsdxShape shape) {
        if ((shape.text ?? '').contains('Name') ||
            shape.richText.runs.any((run) => run.text.contains('Name'))) {
          return shape;
