        inMemory!.richText.textBlock.hideText,
        isFalse,
        reason: 'in-memory Character still paints the unhighlighted remainder',
      );
      expect(
        inMemory.text,
        contains('Confluence'),
        reason: 'the sentence after @Jesse Byler is leftover Character',
      );

      const writer = VsdxWriter();
